#[verus]
pub fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    // Precondition: both arrays must be non-empty
    assert!(!a.is_empty());
    assert!(!b.is_empty());

    // Lengths of the input arrays
    let m = a.len();
    let n = b.len();
    
    // Determine the length of the output arrays
    let max_len = if m > n { m } else { n };

    // Initialize output arrays
    let mut out_a = vec![0; max_len];
    let mut out_b = vec![0; max_len];

    // Invariant: both output arrays must have length max_len
    assert!(out_a.len() == max_len);
    assert!(out_b.len() == max_len);

    // Fill the output arrays according to the broadcasting rules
    if m == 1 && n == 1 {
        // Both arrays have length 1
        out_a[0] = a[0];
        out_b[0] = b[0];
    } else if m == 1 {
        // First array has length 1, second array has length greater than 1
        out_a.fill(a[0]);
        out_b.copy_from_slice(&b);
    } else if n == 1 {
        // Second array has length 1, first array has length greater than 1
        out_a.copy_from_slice(&a);
        out_b.fill(b[0]);
    } else {
        // Both arrays have the same length
        out_a.copy_from_slice(&a);
        out_b.copy_from_slice(&b);
    }

    // Postcondition: both output arrays must have length max_len
    assert!(out_a.len() == max_len);
    assert!(out_b.len() == max_len);

    // Ensure that the contents of the output arrays respect the broadcasting semantics
    for i in 0..max_len {
        if m == 1 {
            assert!(out_a[i] == a[0]);
        } else {
            assert!(out_a[i] == a[i % m]);
        }
        
        if n == 1 {
            assert!(out_b[i] == b[0]);
        } else {
            assert!(out_b[i] == b[i % n]);
        }
    }

    (out_a, out_b)
}